"""French documentation, aligned with the implementation and app terminology."""
from content_en import section, doc
PAGES={}
PAGES['privacy-policy']=doc('Politique de confidentialité','Comment PatternVault traite vos fichiers, autorisations, sauvegardes et partages.','Vos données restent d’abord sur votre appareil. Vous choisissez séparément la sauvegarde et le partage cloud de chaque coffre.',[
section('scope','À propos de cette politique','''<p>{{publisher}} (« nous »), établi au {{country}}, fournit PatternVault pour iPhone et iPad. Cette politique concerne l’app et les échanges avec notre assistance. Aucun compte PatternVault n’est nécessaire. Les fonctions iCloud facultatives nécessitent un compte Apple connecté à iCloud. Pour toute question : {{contact}}.</p>'''),
section('at-a-glance','L’essentiel','''<ul><li>Les fichiers importés, capturés ou créés sont conservés dans le stockage local de l’app.</li><li>Aucun réseau publicitaire, SDK d’analyse tiers ou suivi entre apps n’est intégré.</li><li>Nous ne vendons pas vos informations personnelles et ne les partageons pas à des fins de publicité ciblée.</li><li>Les sauvegardes et copies partagées facultatives sont chiffrées sur l’appareil avant leur envoi à iCloud.</li><li>Les schémas et phrases de récupération ne sont pas transmis à un serveur de comptes du développeur ; PatternVault ne dispose pas d’un tel serveur.</li></ul>'''),
section('local-data','Données présentes sur l’appareil','''<p>PatternVault conserve vos photos, vidéos, notes, documents, miniatures et aperçus ; les noms de coffres, dossiers et fichiers ; les types, dates, tailles et classements ; les vérificateurs de schémas et de phrases, réglages de sécurité et tentatives échouées ; les secrets et identifiants nécessaires aux sauvegardes et partages, libellés de destinataires et compteurs d’ouvertures ; ainsi que les préférences, étapes de configuration et délais d’offres.</p><p>Les fichiers peuvent conserver leurs métadonnées d’origine, y compris une position ajoutée par l’appareil photo source. PatternVault ne garantit pas leur suppression lors de l’importation, de l’exportation ou du partage et ne demande pas l’accès à votre position.</p><p>Les schémas bruts ne sont pas conservés. La récupération ordinaire utilise un vérificateur, pas une phrase lisible. Une nouvelle phrase générée par le mode de contrainte reste temporairement dans l’enregistrement protégé jusqu’à confirmation de sa sauvegarde.</p>'''),
section('protection','Comment fonctionne la protection','''<p>Les fichiers locaux utilisent la protection complète des fichiers d’iOS. Le schéma contrôle l’accès dans l’app ; <strong>les médias locaux ne sont pas chiffrés avec une clé dérivée du schéma</strong>. L’enregistrement des identifiants dispose d’une couche AES-256-GCM liée à l’installation.</p><p>Les archives de sauvegarde iCloud, les fichiers de sauvegarde et les archives partagées utilisent AES-256-GCM. Leurs secrets diffèrent du schéma d’ouverture. PatternVault masque son contenu dans le sélecteur d’apps et se verrouille après passage en arrière-plan.</p><p>Aucune app ne garantit la sécurité d’un appareil compromis ni l’impossibilité de photographier un écran. Consultez le <a href="manual.html#recovery">guide de récupération</a>.</p>'''),
section('icloud','Sauvegarde iCloud facultative','''<p>Désactivée par défaut, elle envoie une archive et des métadonnées de coffre chiffrées dans votre base CloudKit privée. La phrase de récupération protège le secret de restauration ; ni cette phrase ni ce secret ne sont envoyés en clair.</p><p>Apple exploite le service et peut traiter les identifiants de compte ou d’enregistrement, dates, volumes transférés et informations de connexion. Le chiffrement du contenu ne masque pas toutes ces données de service. Consultez la <a href="https://www.apple.com/legal/privacy/">politique Apple</a> et les <a href="https://www.apple.com/legal/internet-services/icloud/en/terms.html">conditions iCloud</a>.</p><p>La sauvegarde s’exécute lorsque le coffre est ouvert et conserve uniquement la dernière version terminée. Elle est distincte de Photos iCloud et de la sauvegarde ordinaire de l’appareil.</p>'''),
section('sharing','Partage de coffres','''<p>Un partage crée une copie cloud chiffrée en lecture seule. Une invitation chiffrée dans la base publique CloudKit permet de la trouver à l’aide d’une phrase de partage. Ce registre ne contient ni médias lisibles ni phrase brute ; des métadonnées de compte et d’enregistrement restent associées au service.</p><p>Le premier compte Apple qui réclame l’invitation devient le destinataire. Il voit le contenu et ses métadonnées et peut exporter si vous l’autorisez. Même sans exportation, il peut photographier l’écran.</p><p>Une copie est mise en cache localement. L’ouverture et la consultation nécessitent des contrôles en ligne. L’expiration, les limites d’ouvertures et le verrouillage après capture sont des règles de l’app, pas une garantie contre la copie. Révoquer un partage n’efface pas les copies conservées ailleurs.</p>'''),
section('permissions','Autorisations sous votre contrôle','''<ul><li><strong>Photos :</strong> le sélecteur système transmet les éléments choisis. Un accès plus large est demandé pour supprimer des originaux après importation réussie et confirmation système. Une destination d’exportation peut demander ses propres autorisations.</li><li><strong>Appareil photo et microphone :</strong> utilisés à l’ouverture de la caméra et pour les vidéos avec son. Une capture reste un brouillon privé jusqu’à « Utiliser » ; aucun enregistrement automatique dans Photos.</li><li><strong>Face ID / Touch ID :</strong> Apple renvoie un résultat d’authentification, jamais votre empreinte ou modèle biométrique à PatternVault.</li><li><strong>Fichiers et partage système :</strong> l’app accède aux documents choisis et transmet ce que vous exportez à la destination sélectionnée, dont les règles s’appliquent ensuite.</li><li><strong>Presse-papiers :</strong> le collage est explicite, sans lecture continue. Les copies de phrases sont locales à l’appareil et expirent.</li></ul><p>Vous pouvez modifier les autorisations dans Réglages. Un refus limite la fonction concernée.</p>'''),
section('purchases','Achats et diagnostics','''<p>Apple gère les paiements. PatternVault utilise les transactions StoreKit et les droits vérifiés, notamment les identifiants de produits et de transactions et leur état, pour activer les fonctions achetées. L’app ne nous transmet pas vos coordonnées de carte.</p><p>Aucun SDK personnalisé d’analyse ou d’envoi de rapports de plantage n’est intégré. Apple peut fournir des statistiques et diagnostics selon vos réglages et ses politiques. Consultez « Analyse et améliorations » et l’<a href="https://www.apple.com/legal/privacy/data/en/app-analytics/">information Apple sur l’analyse des apps</a>.</p>'''),
section('retention','Conservation et suppression','''<ul><li>Les données locales restent jusqu’à la suppression des éléments, du coffre ou de l’app. Supprimer un dossier conserve son contenu ; supprimer un élément ne propose pas de corbeille interne.</li><li>Les fichiers des coffres et la clé d’installation sont exclus des sauvegardes ordinaires de l’appareil. Utilisez les sauvegardes chiffrées de PatternVault.</li><li>« Désactiver et supprimer la sauvegarde cloud » arrête les envois et demande la suppression de la copie configurée, sans supprimer les fichiers locaux.</li><li>Supprimer un coffre personnel supprime ses données et identifiants locaux et programme la suppression de sa sauvegarde cloud et de ses partages. Supprimer un coffre reçu retire seulement votre copie locale.</li><li>Les demandes cloud peuvent attendre une connexion et le bon compte iCloud. Gardez l’app installée et rouvrez-la pour terminer ; la suppression de l’app peut perdre les demandes en attente.</li><li>Supprimer l’app n’efface pas les sauvegardes iCloud terminées, les originaux Photos, les achats ou les exports. « Décharger l’app » conserve les documents et données.</li><li>Gérez séparément les exports et copies des destinataires. Une suppression dans Photos peut se répercuter via Photos iCloud et laisser une copie dans « Supprimées récemment ».</li></ul><p>Le mode de contrainte retire les identifiants des autres coffres mais laisse leurs fichiers sur disque : ce n’est pas un effacement sécurisé. Lisez <a href="manual.html#duress">ses conséquences</a>. Apple et les services destinataires appliquent leurs propres pratiques de conservation, notamment aux journaux et sauvegardes de service.</p>'''),
section('support-rights','Assistance et vos droits','''<p>Nous traitons l’adresse e-mail, les messages et pièces jointes que vous fournissez pour répondre et résoudre les problèmes. Nous les conservons aussi longtemps que raisonnablement nécessaire à ces fins ou aux obligations légales. Des prestataires de messagerie ou d’assistance peuvent intervenir ; des informations peuvent être communiquées si la loi l’exige.</p><p>N’envoyez aucun schéma, phrase de récupération ou de partage, ni fichier privé. Nous n’avons pas de copie serveur permettant de réinitialiser votre schéma ou de déchiffrer une sauvegarde perdue.</p><p>Selon votre pays, vous pouvez disposer de droits d’accès, rectification, suppression, copie, limitation, opposition, retrait du consentement ou réclamation auprès d’une autorité. Contactez {{contact}} pour les données que nous détenons ; une vérification proportionnée peut être nécessaire. Les coffres locaux se gèrent sur votre appareil ; Apple répond de ses propres traitements.</p>'''),
section('children-changes','Mineurs et modifications','''<p>PatternVault ne demande pas de date de naissance et ne crée pas de profil enfant. Les règles du compte Apple, la classification d’âge de l’App Store et les autorisations parentales requises par la loi s’appliquent.</p><p>La date de révision figure en haut. Les changements importants feront l’objet des informations et consentements légalement nécessaires. Cette politique concerne l’app et l’assistance ; d’éventuels autres services web ou outils de suivi nécessitent leurs propres informations.</p>''')])
PAGES['terms-of-use']=doc('Conditions d’utilisation','Les conditions d’utilisation de PatternVault et de ses fonctions cloud facultatives.','Comprenez votre licence, vos responsabilités et les limites de la récupération et du partage.',[
section('agreement','À propos des conditions','''<p>PatternVault est fourni par {{publisher}}, au {{country}}. Vous devez pouvoir accepter les conditions applicables ou disposer de l’autorisation parentale requise. La licence de l’app est l’<a href="https://www.apple.com/legal/internet-services/itunes/dev/stdeula/">accord de licence standard Apple</a>, sauf licence différente fournie avec le téléchargement App Store. Ces conditions le complètent et ne remplacent ni les conditions Apple ni les droits impératifs des consommateurs. Consultez aussi la <a href="privacy-policy.html">Politique de confidentialité</a>.</p>'''),
section('service','Le service','''<p>PatternVault conserve photos, vidéos, notes et documents dans des coffres locaux accessibles par schémas. Il propose aussi biométrie, sauvegardes chiffrées et partage en lecture seule. iOS ou iPadOS 26.2 minimum, matériel compatible, autorisations, espace disponible et services Apple peuvent être nécessaires.</p><p>La version gratuite autorise trois coffres personnels et cinq éléments au total par coffre, tous types et dossiers compris. Les coffres reçus ne comptent pas dans ces limites. Pro supprime ces limites de l’app et permet de créer des partages, sous réserve du stockage disponible.</p>'''),
section('purchases','Achats, offres et remboursements','''<p>Pro est un achat unique non consommable, sans abonnement. Les achats ordinaires et offres spéciales donnent les mêmes fonctions. Prix, taxes, devise et éligibilité sont ceux affichés par Apple ; une offre peut expirer. Apple confirme tout achat.</p><p>« Restaurer les achats » rétablit les droits du compte Apple d’origine, pas les fichiers. Les transactions en attente, annulées ou non vérifiées n’activent pas Pro. Un remboursement ou une révocation peut retirer les fonctions payantes ; les données locales existantes restent consultables, exportables lorsque permis et supprimables, mais les nouveaux ajouts sont limités.</p><p>Apple gère les demandes de remboursement selon ses règles et la loi : <a href="https://support.apple.com/en-us/118223">procédure Apple</a>. Vos recours légaux restent applicables. L’achat unique ne garantit pas la disponibilité perpétuelle de services tiers ni la compatibilité de tout appareil futur.</p>'''),
section('your-content','Vos contenus et votre utilisation','''<p>Vous conservez vos droits sur vos contenus et autorisez uniquement le traitement nécessaire aux opérations choisies : stockage, sauvegarde, export et partage. PatternVault ne nous transfère pas leur propriété.</p><p>Vous devez disposer des droits et consentements nécessaires. N’utilisez pas l’app pour violer la vie privée ou la propriété intellectuelle, exploiter ou maltraiter une personne, diffuser des contenus illégaux, accéder sans autorisation à des données ou perturber des services. La capture silencieuse ne supprime pas les règles de consentement. Il n’existe ni fil public ni annuaire public de coffres.</p>'''),
section('security-recovery','Sécurité et récupération','''<p>Protégez votre appareil, compte Apple, schémas et phrases. Conservez les informations de récupération hors de PatternVault. Les médias locaux utilisent la protection iOS et un verrou d’accès ; leur chiffrement ne dérive pas du schéma. Les archives sont chiffrées séparément. Aucune fonction ne garantit un secret absolu ou la protection d’un appareil compromis.</p><p>Une phrase ne recrée pas des fichiers supprimés. Il faut une sauvegarde terminée et sa phrase valide. Les coffres sont exclus des sauvegardes ordinaires de l’appareil. Vérifiez une copie utilisable avant suppression, réinitialisation ou changement d’appareil. Nous ne pouvons pas récupérer des secrets perdus.</p>'''),
section('cloud-sharing','iCloud et partage','''<p>Ces fonctions dépendent d’Apple, de la connexion, du compte approprié et du stockage. La <a href="https://www.apple.com/legal/privacy/">politique Apple</a> et les <a href="https://www.apple.com/legal/internet-services/icloud/en/terms.html">conditions iCloud</a> s’appliquent. La sauvegarde au premier plan conserve la dernière version terminée ; ce n’est pas une synchronisation bidirectionnelle.</p><p>Une invitation est réclamée par un compte Apple. Le coffre reçu est en lecture seule et contrôlé en ligne. Expiration, limites par installation, exportation et verrouillage après capture ne garantissent pas l’absence de copie. La révocation doit atteindre iCloud et ne supprime pas les copies déjà conservées. Terminez les suppressions cloud souhaitées avant de désinstaller.</p>'''),
section('duress','Contrainte et actions irréversibles','''<p><strong>Le mode de contrainte a des conséquences importantes.</strong> Il arme le schéma du coffre actuel. Une ouverture ultérieure avec ce schéma conserve le coffre leurre choisi, ou le coffre déclencheur en l’absence de leurre, et supprime les identifiants de tous les autres coffres locaux. Il renouvelle la phrase du coffre conservé, arrête sauvegardes et partage sur cette installation et programme la révocation des partages créés.</p><p>Les autres fichiers restent sur disque mais leurs anciens schémas et phrases ne les ouvrent plus. Désactiver le mode n’annule pas ces effets. Une sauvegarde indépendante utilisable peut être restaurée séparément. Ce n’est ni un effacement sécurisé, ni un service d’urgence, ni une garantie de dissimulation. L’échec biométrique ouvrant un leurre ne déclenche pas ce mode. Lisez les confirmations de suppression.</p>'''),
section('availability-liability','Disponibilité et droits légaux','''<p>Nous ne pouvons garantir une disponibilité continue, l’absence d’erreurs ou toute récupération. Les mises à jour peuvent modifier les fonctions ou la compatibilité ; les changements importants seront notifiés lorsque la loi l’exige.</p><p>Les dispositions de garantie, responsabilité, résiliation et litiges de la licence applicable restent en vigueur. Ces conditions n’excluent aucune responsabilité ou protection impérative et n’ajoutent ni arbitrage obligatoire ni tribunal exclusif différent. Vous pouvez cesser l’utilisation ; exportez les fichiers nécessaires et supprimez séparément les copies cloud. Les dispositions qui doivent raisonnablement subsister restent applicables.</p>'''),
section('contact-changes','Contact et révisions','''<p>Contact : {{contact}}. N’envoyez jamais de schéma ou de phrase secrète ; masquez les données privées dans les captures transmises. La date de cette version figure en haut. Les révisions importantes suivent les obligations de notification et de consentement. Les versions traduites ne limitent pas les droits impératifs locaux ; signalez toute divergence de formulation.</p>''')])
PAGES['manual']=doc('Guide d’utilisation','Configurer PatternVault et utiliser ses coffres au quotidien.','Choisissez un schéma, conservez une phrase de récupération, puis ajoutez vos fichiers privés.',[
section('start','1. Créer le premier coffre','''<ol><li>Parcourez ou passez l’introduction, puis choisissez <strong>Créer un nouveau coffre</strong>. Utilisez plutôt la restauration ou l’invitation si vous en avez une.</li><li>Choisissez une grille 3 × 3, 4 × 4 ou 5 × 5 et un nom.</li><li>Dessinez deux fois un schéma d’au moins quatre points distincts. Les points traversés sont ajoutés automatiquement ; aucun point ne peut être réutilisé dans le même geste.</li><li>Conservez la phrase générée de 20 mots, recommandée, ou une phrase personnelle d’au moins huit mots et 40 caractères. Utilisez <strong>Enregistrer dans Notes</strong> ou <strong>Copier la phrase</strong>.</li><li>Répétez toute la phrase et confirmez sa sauvegarde hors de l’app. Les offres d’achat peuvent être fermées pour continuer gratuitement.</li></ol><div class="callout">Gardez la phrase accessible sans cet appareil. Changer d’app conserve la configuration inachevée en mémoire ; terminer le processus peut la perdre.</div><p>PatternVault nécessite iOS/iPadOS 26.2 ou ultérieur.</p>'''),
section('vaults','2. Ouvrir et changer de coffre','''<p>Chaque schéma enregistré ouvre son propre coffre. <strong>Nouveau coffre</strong> dans l’en-tête permet d’en créer un autre, avec un schéma unique confirmé deux fois. Un schéma inconnu ne crée pas de coffre.</p><p>Verrouillez le coffre puis dessinez un autre schéma pour changer. Le passage en arrière-plan verrouille l’app et le sélecteur d’apps masque le contenu. Des erreurs répétées imposent un délai persistant. Gratuit : trois coffres personnels, cinq éléments par coffre ; les coffres reçus ne comptent pas.</p>'''),
section('add','3. Ajouter des fichiers','''<p>Ouvrez le coffre et éventuellement un dossier, puis le bouton d’ajout : médias depuis le sélecteur Photos, appareil photo privé, note ou document depuis Fichiers. Les documents non prévisualisables peuvent être conservés et exportés. Les imports sont des copies et ne suppriment pas la source.</p><p>La suppression des originaux Photos est une action distincte après importation réussie et confirmation système ; elle peut se propager via Photos iCloud. PatternVault ne vide pas « Supprimées récemment ». Les Live Photos sont actuellement importées comme images fixes ; leur original n’est pas supprimé automatiquement. Gardez-le pour conserver l’animation.</p>'''),
section('camera','4. Utiliser l’appareil photo privé','''<ol><li>Choisissez l’appareil photo dans l’ajout et accordez l’autorisation ; le microphone est demandé pour les vidéos avec son.</li><li>Choisissez photo ou vidéo et la caméra disponible, puis capturez.</li><li><strong>Utiliser</strong> conserve la capture dans le coffre/dossier courant. <strong>Reprendre</strong>, annuler ou passer en arrière-plan abandonne le brouillon non confirmé.</li></ol><p>Aucune copie automatique n’est ajoutée à Photos. Le bouton de haut-parleur barré utilise des images ARKit pour la photo silencieuse sur les caméras compatibles, avec moins de détails possibles qu’une photo normale. Il ne coupe pas le son des vidéos. L’interface système de capture ou de contrôle peut rester sombre.</p>'''),
section('organize','5. Rechercher et organiser','''<ul><li><strong>Recherche :</strong> noms d’éléments/fichiers dans le dossier ou la bibliothèque actuelle, combinée au filtre ; pas le texte interne des documents. Changer de dossier ou ajouter du contenu efface la recherche.</li><li><strong>Tri :</strong> icône de flèches, par date d’importation, nom, date du fichier ou taille croissante/décroissante. La date utilise les métadonnées disponibles, sinon une date de remplacement.</li><li><strong>Filtre :</strong> tous les éléments, photos, vidéos, notes ou documents.</li><li><strong>Sélection :</strong> icône de coche entourée pour sélectionner, tout sélectionner, déplacer, exporter ou supprimer ; touchez-la de nouveau pour terminer.</li><li><strong>Dossiers :</strong> créer, renommer, recolorer, déplacer des éléments ou supprimer. Supprimer un dossier conserve ses éléments.</li></ul><p>Sur les grands iPad, une barre latérale facilite la navigation. Les photos se parcourent et se zooment ; la lecture vidéo s’arrête lorsque vous quittez la vidéo ou l’app.</p>'''),
section('export-delete','6. Exporter et supprimer','''<p>Sélectionnez des éléments puis exportez vers Fichiers ou une destination de la feuille de partage. Il s’agit de copies ordinaires, avec des métadonnées possibles, pas d’archives chiffrées PatternVault. Pour celles-ci, utilisez la <a href="#file-backup">sauvegarde dans un fichier</a>.</p><p>Un coffre reçu n’autorise l’export que si son propriétaire l’a permis. La suppression confirmée retire les copies de l’app sans corbeille interne, pas les originaux Photos ni les anciens exports.</p>'''),
section('recovery','7. Schémas, phrases et grille','''<p>Dans <strong>Réglages du coffre</strong>, confirmez le schéma actuel puis le nouveau deux fois. En cas d’oubli, <strong>Récupérer le coffre</strong> sur l’écran verrouillé permet d’utiliser sa phrase de récupération. Les erreurs répétées entraînent un délai.</p><p>Pour remplacer une phrase, enregistrez la nouvelle hors de l’app, répétez-la et confirmez le schéma actuel. L’ancienne cesse immédiatement de fonctionner pour la récupération locale. Une sauvegarde iCloud existante utilise encore l’ancienne jusqu’à la prochaine sauvegarde terminée ; un fichier exporté exige toujours sa phrase d’origine.</p><p>Le changement de grille concerne tous les coffres : confirmez chaque ancien schéma, dessinez chaque nouveau schéma unique deux fois, effectuez la biométrie si un coffre l’exige et validez. Annuler ne change rien ; réussir verrouille les fenêtres ouvertes.</p><div class="callout">La récupération d’un schéma ne remplace pas une sauvegarde. Des fichiers supprimés nécessitent aussi une archive utilisable.</div>'''),
section('icloud-backup','8. Sauvegarder dans iCloud','''<ol><li>Ouvrez un coffre personnel et <strong>Sauvegarde iCloud chiffrée</strong> dans les réglages.</li><li>Saisissez sa phrase de récupération et activez la sauvegarde.</li><li>Gardez le coffre ouvert, connecté, avec assez de stockage, jusqu’à l’affichage d’une date de sauvegarde terminée.</li><li>Lancez une sauvegarde immédiate avant de changer d’appareil. Rouvrez le coffre pour réessayer après interruption.</li></ol><p>Chaque coffre s’active séparément. Une seule dernière version terminée est conservée, sans historique ni synchronisation bidirectionnelle. <strong>Désactiver et supprimer la sauvegarde cloud</strong> demande son retrait tout en gardant les fichiers locaux. Les demandes en attente exigent le bon compte iCloud et une connexion.</p>'''),
section('restore','9. Restaurer depuis iCloud','''<ol><li>Connectez le compte Apple propriétaire de la sauvegarde.</li><li>Choisissez <strong>Restaurer depuis iCloud</strong> dans la configuration, l’écran verrouillé ou les réglages de sauvegarde.</li><li>Sélectionnez une sauvegarde datée et saisissez la phrase correspondant à son dernier envoi terminé.</li><li>Choisissez un nom local unique et un nouveau schéma.</li><li>Configurez ensuite une nouvelle phrase de récupération et réactivez les futures sauvegardes si souhaité.</li></ol><p>La restauration crée un coffre distinct sans en écraser un autre. Les noms sont chiffrés, d’où la liste initiale par date. Les limites gratuites sont vérifiées avant installation ; les archives trop grandes ne sont pas tronquées. Sans sauvegarde terminée, une phrase seule ne recrée pas les médias.</p>'''),
section('file-backup','10. Utiliser un fichier de sauvegarde','''<p>Ouvrez <strong>Sauvegarde dans un fichier → Exporter un fichier de sauvegarde</strong>, saisissez la phrase et enregistrez le fichier <code>.patternbackup</code> via Fichiers. Conservez phrase et fichier séparément ; attendez la fin du transfert si la destination est iCloud Drive ou un autre cloud.</p><p>C’est un instantané : exportez de nouveau pour inclure les changements. <strong>Importer un fichier de sauvegarde</strong> demande l’archive et sa phrase d’origine, puis crée un coffre. Changer la phrase actuelle ne réécrit pas les anciens fichiers.</p>'''),
section('share','11. Partager ou recevoir un coffre','''<p>Avec Pro, ouvrez <strong>Partage</strong> dans les réglages d’un coffre personnel. Choisissez éventuellement un libellé de destinataire, une expiration, une limite d’ouvertures, l’autorisation d’export et le verrouillage après capture. Appuyez sur <strong>Créer une phrase de partage</strong>, attendez l’envoi, puis transmettez la phrase en privé. Elle ne sera plus affichée après avoir quitté cet écran. Ne transmettez pas votre phrase de récupération.</p><p>Le destinataire choisit <strong>Rejoindre un coffre partagé</strong>, saisit la phrase en étant connecté à iCloud puis définit un nom et un schéma locaux. Le premier compte Apple qui réclame l’invitation devient le destinataire ; il peut la réimporter avec la même phrase. Recevoir est gratuit, hors quotas des coffres personnels.</p><p>Le coffre reçu est en lecture seule et nécessite des vérifications en ligne à l’ouverture et pendant la consultation. Le propriétaire envoie les mises à jour lorsqu’il ouvre son coffre ; le destinataire les reçoit à la réouverture.</p><p>Révoquez l’accès dans Partage et gardez l’app installée jusqu’à la fin des demandes cloud. Les compteurs sont propres à l’installation et peuvent être réinitialisés par suppression/réinstallation. Le verrouillage après détection ne bloque pas la première capture ni une caméra externe. Les exports déjà faits restent accessibles hors de PatternVault.</p>'''),
section('biometrics','12. Biométrie et coffre leurre','''<p>Dans <strong>Face ID et coffre leurre</strong> ou l’équivalent Touch ID, choisissez un autre coffre existant, activez la protection et suivez les confirmations de schémas et biométriques. Le schéma sélectionne le coffre protégé ; la biométrie l’ouvre, sans remplacement par le code de l’appareil.</p><p>Un échec, refus, annulation ou indisponibilité affiche le leurre choisi ; une interruption système maintient le verrouillage. La session leurre permet les opérations sur les médias, mais pas les réglages ou la création de coffres. Son propre schéma donne l’accès complet. Si le leurre a été supprimé, un échec reste verrouillé. <strong>Un échec biométrique n’active pas le mode de contrainte.</strong></p>'''),
section('duress','13. Comprendre le mode de contrainte','''<div class="callout warning">N’activez ni ne testez cette fonction avec des données irremplaçables sans sauvegarde indépendante utilisable.</div><p><strong>Utiliser un coffre de contrainte</strong> arme le schéma actuel après explication, accord et confirmation. La configuration ne déclenche rien immédiatement. Lors d’une ouverture ultérieure avec ce schéma :</p><ul><li>Le leurre choisi est conservé, sinon le coffre déclencheur. Si un autre leurre est conservé, le coffre déclencheur perd lui aussi l’accès.</li><li>Les identifiants de tous les autres coffres locaux sont retirés ; leurs anciens schémas et phrases cessent de les ouvrir, même si les fichiers restent sur disque.</li><li>Le coffre conservé reçoit une nouvelle phrase : utilisez <strong>Sauvegarder la nouvelle phrase</strong> et gardez-la hors de l’app.</li><li>Les sauvegardes cloud et manuelles ainsi que le partage s’arrêtent sur cette installation. Les partages créés sont programmés pour révocation. Les anciennes sauvegardes personnelles et fichiers exportés ne sont pas effacés.</li></ul><p>Désactiver le mode ne rend pas les accès ni ne réactive les sauvegardes. Restaurer une sauvegarde indépendante est une autre action. Confirmer un schéma dans les réglages ne déclenche pas le mode. Ce n’est pas un effacement sécurisé ni une garantie de dissimulation.</p>'''),
section('icons-language','14. Icône et langue','''<p>Dans <strong>Réglages de l’app → Icône de l’app</strong>, choisissez un style ; Classic remet l’icône principale. Le changement concerne tous les coffres de l’appareil, sans modifier l’accès ni le nom installé.</p><p>Le guide de nom sur l’écran d’accueil aide à créer un lanceur nommé dans Raccourcis Apple, avec « Ouvrir l’app → PatternVault » et l’illustration choisie. C’est un raccourci distinct ; l’app d’origine n’est ni renommée, ni masquée, ni supprimée.</p><p>Langues : anglais, japonais, coréen, français, allemand, italien et chinois simplifié. Modifiez la langue dans Réglages système si disponible. Vos noms de fichiers et mots de phrases ne sont pas traduits.</p>'''),
section('purchases-removal','15. Achats, suppression et assistance','''<p><strong>PatternVault Pro</strong> permet l’achat unique ou <strong>Restaurer les achats</strong> avec le compte Apple d’origine. Offre ordinaire et offre spéciale donnent les mêmes fonctions ; restaurer l’achat ne restaure pas les médias.</p><p>Supprimer un coffre exige son nom et schéma actuel, supprime son contenu et ses identifiants locaux et, s’il vous appartient, demande le retrait de sa sauvegarde cloud et de ses partages. Les autres coffres, originaux Photos et exports restent. Supprimer un coffre reçu retire uniquement sa copie locale.</p><p>Supprimer l’app retire ses coffres locaux et sa clé d’installation ; la décharger conserve les données. Vérifiez une sauvegarde et terminez les suppressions cloud avant suppression. Consultez la <a href="faq.html">FAQ</a> ou {{contact}}, avec versions app/iOS et message d’erreur, jamais de phrase secrète.</p>''')])
FAQ=[
('basics','Premiers pas',[
('account','Faut-il un compte ?','Pas de compte PatternVault. Vos coffres personnels fonctionnent hors ligne. Les sauvegardes et partages iCloud nécessitent un compte Apple connecté et une connexion.'),
('free','Que comprend la version gratuite ?','Trois coffres personnels et cinq éléments par coffre, tous types et dossiers compris. Recevoir un partage est gratuit et hors quotas. Pro supprime les limites de l’app et permet de créer des partages ; le stockage disponible reste limité.'),
('patterns','Chaque schéma ouvre-t-il un coffre différent ?','Oui, parmi les coffres créés. Utilisez Nouveau coffre pour en ajouter un ; un schéma inconnu ne crée rien.'),
('grid','Puis-je changer la taille de la grille ?','Oui, entre 3 × 3, 4 × 4 et 5 × 5, pour tous les coffres à la fois. Vous confirmez leurs anciens schémas et définissez des remplacements uniques. <a href="manual.html#recovery">Voir la procédure.</a>'),
('subscription','Pro est-il un abonnement ?','Non. Achat ordinaire et offre spéciale sont des achats uniques non consommables donnant les mêmes fonctions. Le prix affiché par Apple s’applique.')]),
('files','Fichiers et caméra',[
('originals','Importer supprime-t-il les originaux ?','Non. PatternVault les copie. Supprimer les originaux Photos est une action séparée après importation et confirmation ; elle peut se propager via iCloud. PatternVault ne vide pas Supprimées récemment. Les documents source restent aussi en place.'),
('live-photos','Qu’en est-il des Live Photos ?','Seule l’image fixe est importée actuellement. L’original Live Photo n’est pas supprimé automatiquement ; gardez-le pour conserver le mouvement.'),
('camera-photos','Les captures vont-elles dans Photos ?','Pas automatiquement. Utiliser les enregistre dans le coffre/dossier courant. Reprendre, annuler ou passer en arrière-plan abandonne les captures non confirmées. Vous pouvez exporter plus tard.'),
('silent','Pourquoi la photo silencieuse est-elle indisponible ou moins détaillée ?','Elle utilise une image vidéo ARKit sur les caméras compatibles, pas la capture photo haute résolution habituelle. Les détails peuvent être moindres. Ce réglage ne coupe pas le son vidéo.'),
('search','Pourquoi un fichier manque-t-il dans la recherche ?','La recherche concerne les noms dans le dossier ou la bibliothèque actuelle et respecte le filtre, pas le contenu des documents. Vérifiez le dossier et le filtre. Changer de dossier ou ajouter du contenu efface la recherche.'),
('folder-delete','Supprimer un dossier supprime-t-il son contenu ?','Non, ses éléments restent dans le coffre. Supprimer les éléments eux-mêmes est une action distincte après confirmation.'),
('metadata','Les métadonnées sont-elles supprimées ?','Pas systématiquement. Dates ou positions de la source peuvent rester dans les copies importées, exportées et partagées. PatternVault n’est pas un outil de nettoyage des métadonnées.')]),
('security','Protection et récupération',[
('encryption','Le schéma chiffre-t-il tous mes fichiers ?','Non. Il contrôle l’accès dans l’app. Les fichiers locaux utilisent la protection complète iOS ; les identifiants ont un chiffrement lié à l’installation. Les archives cloud et portables utilisent AES-256-GCM avec des secrets distincts du schéma.'),
('forgot','J’ai oublié mon schéma. Que faire ?','Utilisez Récupérer le coffre avec sa phrase de récupération. Sans schéma ni phrase, l’assistance ne peut pas contourner le verrou. Une sauvegarde utilisable et sa phrase d’origine permettent une restauration séparée.'),
('deleted-app','Une phrase suffit-elle après suppression de l’app ?','Non : il faut aussi une sauvegarde cloud terminée ou un fichier .patternbackup. La phrase ne contient pas les fichiers. Réinstaller ou restaurer l’achat ne restaure pas les coffres, exclus des sauvegardes ordinaires de l’appareil.'),
('changed-phrase','Quelle phrase ouvre une ancienne sauvegarde ?','Un fichier exporté utilise toujours sa phrase de création. Après un changement, la copie cloud utilise l’ancienne jusqu’à la prochaine sauvegarde terminée. La récupération locale utilise immédiatement la nouvelle.'),
('biometric-dummy','Pourquoi la biométrie ouvre-t-elle un autre coffre ?','Le leurre configuré s’ouvre en cas d’échec, d’annulation ou d’indisponibilité. Cela ne déclenche pas la contrainte et ne modifie pas les sauvegardes. Une interruption système maintient le verrou. Le schéma propre du leurre donne accès à ses réglages.'),
('duress-effect','Que fait exactement la contrainte ?','Le schéma armé conserve le leurre choisi, ou le coffre déclencheur à défaut, retire les identifiants de tous les autres coffres locaux, renouvelle la phrase du survivant, arrête sauvegardes/partage et programme les révocations. Les autres fichiers restent sur disque. Désactiver ne rétablit rien. <a href="manual.html#duress">Lisez tous les effets.</a>'),
('capture','Les captures d’écran sont-elles impossibles ?','Non. Le verrouillage d’un coffre partagé après détection peut couper l’accès, mais ne garantit pas d’empêcher la première capture ou une photo prise avec un autre appareil.')]),
('cloud','Sauvegarde et partage',[
('sync','iCloud synchronise-t-il automatiquement tous mes appareils ?','Non. La sauvegarde fonctionne avec le coffre ouvert et conserve la dernière copie terminée. Restaurer crée un coffre indépendant ; il n’y a ni synchronisation bidirectionnelle ni historique de versions.'),
('backup-failure','Ma sauvegarde ne se termine pas.','Vérifiez connexion, stockage local/iCloud et compte Apple d’origine. Ouvrez le coffre et relancez une sauvegarde, puis vérifiez sa date de fin. Notez l’erreur pour l’assistance. Ne supprimez pas l’app pour dépanner sans sauvegarde vérifiée.'),
('no-backups','Pourquoi aucune sauvegarde n’apparaît-elle ?','Utilisez le compte propriétaire et vérifiez qu’un envoi a été terminé. Sauvegarde appareil, Photos iCloud et fichiers iCloud Drive sont distincts. Pour un fichier .patternbackup, choisissez Importer un fichier de sauvegarde.'),
('shared-offline','Puis-je ouvrir un coffre reçu hors ligne ?','Non : un contrôle en ligne précède l’ouverture et se répète pendant la consultation. Vos coffres personnels peuvent fonctionner hors ligne. L’export d’un coffre reçu dépend en plus de l’autorisation du propriétaire.'),
('sharing-phrase','Phrase de partage et phrase de récupération sont-elles identiques ?','Non. Envoyez seulement la phrase de partage générée. Le premier compte Apple qui la réclame devient le destinataire et peut la réutiliser pour réimporter. Gardez schéma et phrase de récupération secrets.'),
('revoke','La révocation efface-t-elle tout chez le destinataire ?','Non. Elle empêche l’accès par le partage après transmission à iCloud et contrôle d’autorisation. Les exports, captures et photos externes restent. Gardez PatternVault installé pour terminer les révocations en attente.'),
('open-limit','Les ouvertures sont-elles comptées sur tous les appareils ?','Non, le compteur est local à chaque installation et persiste au redémarrage. Supprimer le coffre reçu ou réinstaller peut le réinitialiser. Il ne protège pas contre un contournement délibéré.'),
('remove-cloud','Comment supprimer la sauvegarde cloud ?','Choisissez Désactiver et supprimer la sauvegarde cloud dans les réglages du coffre. Le retrait demande iCloud ; les fichiers locaux restent. Supprimer seulement l’app ne retire pas une sauvegarde terminée. <a href="privacy-policy.html#retention">Voir la conservation.</a>')]),
('appearance-help','Apparence, achats et aide',[
('icon-name','L’icône change-t-elle le nom de l’app ?','Non, l’app installée reste PatternVault. Le guide propose un lanceur distinct et nommé dans Raccourcis Apple, sans renommer ni masquer l’original.'),
('restore-purchase','Comment restaurer Pro ?','Avec le compte Apple de l’achat, ouvrez PatternVault Pro puis Restaurer les achats. Apple peut demander une connexion. Cela restaure les fonctions ; restaurez vos fichiers depuis leurs sauvegardes.'),
('refund','Comment demander un remboursement ?','Utilisez la <a href="https://support.apple.com/en-us/118223">procédure Apple</a>. L’éligibilité dépend de l’achat, du pays et de la loi. Si Pro est retiré, l’app actuelle conserve l’accès aux données locales existantes et limite les nouveaux ajouts.'),
('help','Que transmettre à l’assistance ?','À {{contact}}, indiquez versions app/iOS, étapes et erreur. Masquez les données privées des captures. N’envoyez ni fichiers de coffre, ni schémas, ni phrases de récupération/partage, ni coordonnées de carte.')])]
PAGES['faq']=dict(title='Questions fréquentes',description='Réponses sur la confidentialité, la récupération, iCloud et l’utilisation quotidienne.',lead='Des réponses pratiques et des liens vers les étapes utiles.',faq=FAQ)
